  "questions": [
    {
      "column": "invoice_status",
      "label": "Which Invoice Population?",
      "choices": [
        {
          "id": "paid",
          "label": "Delivered / Paid",
          "value": "STATUS_PAID"
        },
        {
          "id": "ordered",
          "label": "Acknowledged / Awaiting Collection",
          "value": "STATUS_ACKNOWLEDGED"
        },
        {
          "id": "cancelled",
          "label": "Cancelled",
          "value": "STATUS_CANCELLED"
        },
        {
          "id": "all",
          "label": "All Statuses (Includes Cancelled)"
        }
      ]
    },
    {
      "column": "invoice_credited",
      "label": "How Should Credited Invoices Be Treated?",
      "choices": [
        {
          "id": "exclude",
          "label": "Exclude Credits",
          "value": false
        },
        {
          "id": "only",
          "label": "Credits Only",
          "value": true
        },
        {
          "id": "all",
          "label": "Include Credits"
        }
      ]
    },
    {
      "column": "sales_type_bucket",
      "label": "Which Sales Type? Price Averages Need Separate 0% Treatment.",
      "choices": [
        {
          "id": "rate",
          "label": "Rate / Cash",
          "value": "Rate/Cash"
        },
        {
          "id": "zero",
          "label": "Interest Free Only",
          "value": "0%"
        },
        {
          "id": "unknown",
          "label": "Unknown Only",
          "value": "Unknown"
        },
        {
          "id": "all",
          "label": "All (Confirm Separate Price Comparisons)"
        }
      ]
    }
  ]
}

